package me.pikanote.companion;
import android.content.*;import android.net.*;import org.json.*;import java.io.*;import java.nio.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.security.*;import java.time.*;import java.util.*;import javax.net.ssl.HttpsURLConnection;import java.net.URL;
final class PhoneVoice {
 static volatile String activeUpload="";
 static final long MAX_BYTES=25000000,MIN_PCM=16000;
 interface Transcriber {String transcribe(File wav,String key)throws Exception;}
 static String fileName(String token)throws IOException{if(!token.matches("[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}"))throw new IOException("Invalid recording ID");return ".phone-voice-"+token+".wav";}
 static JSONArray jobs(Store store)throws Exception{synchronized(store){JSONArray list=store.state.optJSONArray("voiceCaptures");if(list==null){list=new JSONArray();store.state.put("voiceCaptures",list);}return list;}}
 static JSONObject job(Store store,String token)throws Exception{synchronized(store){JSONArray list=jobs(store);for(int i=0;i<list.length();i++)if(list.getJSONObject(i).optString("token").equals(token))return list.getJSONObject(i);throw new IOException("Recording not found");}}
 static JSONObject transferState(Store store)throws Exception{synchronized(store){Set<String> pending=new LinkedHashSet<>();String active="";JSONArray rows=jobs(store);for(int n=0;n<rows.length();n++){JSONObject j=rows.getJSONObject(n);if(j.optBoolean("hidden")||j.optBoolean("audioDelivered")||j.optString("status").equals("done"))continue;String id=store.id(j.optString("localId"));if(id.isEmpty())continue;pending.add(id);if(j.optString("token").equals(activeUpload))active=id;}JSONArray edits=store.state.optJSONArray("pending");if(edits!=null)for(int n=0;n<edits.length();n++){JSONObject op=edits.getJSONObject(n),body=op.optJSONObject("body");if(body!=null&&body.optString("kind").equals("memories")){String id=store.id(op.optString("localId",body.optString("id")));if(!id.isEmpty())pending.add(id);}}return new JSONObject().put("active",active).put("pending",new JSONArray(pending));}}
 static JSONArray summary(Store store)throws Exception{synchronized(store){JSONArray out=new JSONArray(),list=jobs(store);for(int i=0;i<list.length();i++){JSONObject j=list.getJSONObject(i);if(j.optBoolean("hidden"))continue;out.put(new JSONObject().put("token",j.getString("token")).put("status",j.optString("status")).put("error",j.optString("uploadError",j.optString("error"))).put("createdUtc",j.optString("createdUtc")).put("durationMs",j.optLong("durationMs")).put("id",store.id(j.optString("localId"))));}return out;}}
 static void enqueue(Store store,String token,long duration,String created)throws Exception{synchronized(store){File file=store.safeFile(fileName(token));if(!file.isFile()||file.length()<44+MIN_PCM||file.length()>MAX_BYTES)throw new IOException("Recording must be at least 0.5 seconds");for(int i=0;i<jobs(store).length();i++)if(jobs(store).getJSONObject(i).optString("token").equals(token))return;jobs(store).put(new JSONObject().put("token",token).put("file",file.getName()).put("createdUtc",created).put("durationMs",duration).put("status","queued").put("attempt",0));store.save();}kick();}
 static void kick(){PikaService service=PikaService.instance;if(service!=null)service.scheduleVoice();}
 static boolean pendingUploads(Store store){synchronized(store){try{JSONArray list=jobs(store);for(int i=0;i<list.length();i++){JSONObject j=list.getJSONObject(i);if(!j.optBoolean("hidden")&&!j.optString("status").equals("done")&&!j.optString("localId").isEmpty())return true;}}catch(Exception ignored){}return false;}}
 static void retryUploadsNow(Store store){synchronized(store){try{JSONArray list=jobs(store);boolean changed=false;for(int i=0;i<list.length();i++){JSONObject j=list.getJSONObject(i);if(!j.optBoolean("hidden")&&Arrays.asList("ready","uploading").contains(j.optString("status"))&&j.optLong("retryAt")>0){j.put("retryAt",0);changed=true;}}if(changed)store.save();}catch(Exception ignored){}}}
 static boolean hasUploads(Store store){synchronized(store){try{JSONArray list=jobs(store);for(int i=0;i<list.length();i++){JSONObject job=list.getJSONObject(i);String status=job.optString("status");if((status.equals("ready")||status.equals("uploading"))&&job.optLong("retryAt")<=System.currentTimeMillis())return true;}}catch(Exception ignored){}return false;}}
 static void rememberKey(Store store,String value)throws Exception{if(value==null||value.trim().length()<10)return;synchronized(store){JSONObject secrets=store.state.optJSONObject("settingsSecrets");if(secrets==null){secrets=new JSONObject();store.state.put("settingsSecrets",secrets);}if(!value.equals(secrets.optString("apiKey"))){secrets.put("apiKey",value);store.save();}}}
 static String key(Store store){synchronized(store){JSONObject secrets=store.state.optJSONObject("settingsSecrets");return secrets==null?"":secrets.optString("apiKey");}}
 static boolean connected(Context context){ConnectivityManager cm=context.getSystemService(ConnectivityManager.class);Network network=cm.getActiveNetwork();NetworkCapabilities caps=network==null?null:cm.getNetworkCapabilities(network);return caps!=null&&caps.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET)&&caps.hasCapability(NetworkCapabilities.NET_CAPABILITY_VALIDATED);}
 static void recover(Store store)throws Exception{synchronized(store){File[] files=store.mirror.listFiles((d,n)->n.startsWith(".phone-voice-")&&n.endsWith(".wav"));if(files!=null)for(File file:files){String token=file.getName().substring(13,file.getName().length()-4);try{fileName(token);boolean found=false;for(int i=0;i<jobs(store).length();i++)found|=jobs(store).getJSONObject(i).optString("token").equals(token);if(!found&&file.length()>=44+MIN_PCM)jobs(store).put(new JSONObject().put("token",token).put("file",file.getName()).put("createdUtc",Instant.ofEpochMilli(file.lastModified()).toString()).put("durationMs",(file.length()-44)*1000/32000).put("status","queued"));}catch(IOException ignored){}}JSONArray list=jobs(store);for(int i=0;i<list.length();i++)if(list.getJSONObject(i).optString("status").equals("transcribing"))list.getJSONObject(i).put("status","queued");store.save();}}
 static void retry(Store store,String token)throws Exception{synchronized(store){JSONObject job=job(store,token);if(job.optString("localId").isEmpty())job.put("status","queued");else job.put("status","ready");job.remove("error");job.remove("uploadError");job.remove("permanentError");job.put("retryAt",0);store.save();}kick();}
 static void discard(Store store,String token)throws Exception{synchronized(store){JSONObject job=job(store,token);if(!job.optString("localId").isEmpty())throw new IOException("Forget the saved memory to archive it");if(job.optString("status").equals("transcribing"))throw new IOException("Wait until transcription finishes");store.safeFile(job.getString("file")).delete();JSONArray list=jobs(store);for(int i=list.length()-1;i>=0;i--)if(list.getJSONObject(i).optString("token").equals(token))list.remove(i);store.save();}}
 static void process(Store store,BleTransport ble)throws Exception{
  if(key(store).isEmpty()&&ble!=null&&ble.online&&!ble.deviceBusy){BleTransport.Reply config=ble.rpc("/api/phone/voice-config","GET",null,null);if(config.status==200)rememberKey(store,config.json().optString("apiKey"));}
  if(!connected(store.context)||key(store).isEmpty())return;
  processOne(store,PhoneVoice::transcribe);
 }
 static void processOne(Store store,Transcriber transcriber)throws Exception{
  String token="";synchronized(store){JSONArray list=jobs(store);for(int i=0;i<list.length();i++){JSONObject j=list.getJSONObject(i);String status=j.optString("status");if((status.equals("queued")||status.equals("error"))&&j.optLong("retryAt")<=System.currentTimeMillis()&&!j.optBoolean("permanentError")){token=j.getString("token");j.put("status","transcribing").remove("error");store.save();break;}}}if(token.isEmpty())return;
  synchronized(store){JSONObject j=job(store,token);if(OfflineInbox.manual(store,j)){j.put("status","manual").put("hidden",true);store.save();return;}}
  try{JSONObject details;String savedKey;synchronized(store){details=new JSONObject(job(store,token).toString());savedKey=key(store);}String transcript=transcriber.transcribe(store.safeFile(details.getString("file")),savedKey).trim();if(transcript.isEmpty())throw new IOException("No speech recognized. The WAV is kept; retry or delete it.");if(transcript.getBytes(StandardCharsets.UTF_8).length>32000)throw new IOException("Transcript exceeds the 32000-byte memory limit. The WAV is kept.");finishTranscript(store,token,transcript);}
  catch(Exception error){ErrorJournal.add(store.context,"voice","transcription",error.getClass().getSimpleName()+": "+error.getMessage());synchronized(store){JSONObject j=job(store,token);int attempts=j.optInt("attempt")+1;j.put("attempt",attempts).put("status","error").put("error",error.getMessage()==null?"Transcription failed; WAV kept":error.getMessage()).put("retryAt",System.currentTimeMillis()+Math.min(300000,15000L*(1L<<Math.min(attempts,4))));if(error instanceof KeyError)j.put("permanentError",true);store.save();}}
 }
 static void finishTranscript(Store store,String token,String transcript)throws Exception{synchronized(store){JSONObject j=job(store,token);
 if(!j.optString("sourceId").isEmpty()){
  if(OfflineInbox.manual(store,j)){j.put("status","manual").put("hidden",true);store.save();return;}
  String id=store.id(j.getString("sourceId"));JSONObject current=store.find(store.snapshot(),"memories",id);JSONObject record=new JSONObject(current.toString()).put("text",transcript);
  store.queueMutation(new JSONObject().put("kind","memories").put("action","save").put("id",id).put("clientRequest","device-transcript-"+token).put("automaticTranscript",true).put("record",record));
  j.put("status","done").put("hidden",true).put("transcript",transcript);store.save();store.requestSync();return;
 }
String date=Instant.parse(j.getString("createdUtc")).atZone(ZoneId.of("Europe/Kyiv")).format(java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm",Locale.ROOT));JSONObject record=new JSONObject().put("text",transcript).put("date",date).put("phoneVoice",token);JSONObject request=new JSONObject().put("kind","memories").put("action","save").put("id","").put("clientRequest","voice-"+token).put("record",record);String local=store.queueMutation(request).json().getString("id");j.put("localId",local).put("status","ready").put("transcript",transcript);j.remove("error");j.remove("permanentError");store.save();}store.requestSync();}
 static final class KeyError extends IOException{KeyError(){super("Check the AI API key in Config. Your recording is kept.");}}
 static String transcribe(File wav,String key)throws Exception{
  String boundary="PikaVoice"+UUID.randomUUID().toString().replace("-","");byte[] head=("--"+boundary+"\r\nContent-Disposition: form-data; name=\"model\"\r\n\r\ngpt-4o-mini-transcribe\r\n--"+boundary+"\r\nContent-Disposition: form-data; name=\"file\"; filename=\"memory.wav\"\r\nContent-Type: audio/wav\r\n\r\n").getBytes(StandardCharsets.UTF_8),tail=("\r\n--"+boundary+"--\r\n").getBytes(StandardCharsets.UTF_8);
  HttpsURLConnection connection=(HttpsURLConnection)new URL("https://api.openai.com/v1/audio/transcriptions").openConnection();try{connection.setConnectTimeout(15000);connection.setReadTimeout(90000);connection.setRequestMethod("POST");connection.setRequestProperty("Authorization","Bearer "+key);connection.setRequestProperty("Content-Type","multipart/form-data; boundary="+boundary);connection.setDoOutput(true);connection.setFixedLengthStreamingMode(head.length+wav.length()+tail.length);try(OutputStream out=connection.getOutputStream();InputStream in=new FileInputStream(wav)){out.write(head);byte[] buf=new byte[16384];int n;while((n=in.read(buf))>=0)if(n>0)out.write(buf,0,n);out.write(tail);}int code=connection.getResponseCode();if(code==401||code==403)throw new KeyError();if(code!=200)throw new IOException("Transcription HTTP "+code+". Recording kept for retry.");try(InputStream in=connection.getInputStream()){ByteArrayOutputStream out=new ByteArrayOutputStream();PhoneBackup.copyBounded(in,out,262144);return new JSONObject(out.toString("UTF-8")).optString("text");}}finally{connection.disconnect();}
 }
 static boolean uploadPending(Store store,BleTransport ble)throws Exception{
  List<String> tokens=new ArrayList<>();synchronized(store){JSONArray list=jobs(store);for(int i=0;i<list.length();i++){JSONObject j=list.getJSONObject(i);String status=j.optString("status");if((status.equals("ready")||status.equals("uploading"))&&j.optLong("retryAt")<=System.currentTimeMillis())tokens.add(j.getString("token"));}}
  if(tokens.isEmpty())return false;final long connection=ble.session;ble.rpc("/api/phone/lease","GET",null,new JSONObject().put("active",true));long started=System.currentTimeMillis(),sent=0;boolean changed=false;String currentToken="";try{for(String token:tokens){currentToken=token;if(!ble.online||ble.deviceBusy)throw new Store.SyncDeferredException();JSONObject j;String id;synchronized(store){j=new JSONObject(job(store,token).toString());id=store.id(j.optString("localId"));JSONObject memory=store.find(store.snapshot(),"memories",id);if(memory==null||memory.optBoolean("archived")){job(store,token).put("status","done").put("hidden",true);store.save();continue;}}
   if(!id.matches("m[0-9]+"))continue;File wav=store.safeFile(j.getString("file"));if(!wav.isFile())throw new IOException("Voice recording unavailable on phone");String hash=hash(wav);JSONObject base=new JSONObject().put("id",id).put("token",token).put("sha256",hash).put("size",wav.length());synchronized(store){activeUpload=j.optBoolean("audioDelivered")?"":token;store.syncMessage="Sending voice memory · 0%";job(store,token).put("status","uploading");store.save();}JSONObject reply=request(ble,base,"begin");if(!reply.optBoolean("done")){long offset=reply.getLong("offset");try(RandomAccessFile in=new RandomAccessFile(wav,"r")){byte[] buffer=new byte[Math.max(3072,Math.min(32768,reply.optInt("chunkBytes",3072)))];while(offset<wav.length()){if(ble.deviceBusy)throw new Store.SyncDeferredException();in.seek(offset);int n=in.read(buffer,0,(int)Math.min(buffer.length,wav.length()-offset));if(n<=0)throw new IOException("Recording read failed");JSONObject chunk=chunkForWire(base,offset,buffer,n);reply=request(ble,chunk,"chunk");long next=reply.getLong("offset");if(next<=offset||next>wav.length())throw new IOException("Invalid recording upload offset");sent+=next-offset;offset=next;store.syncMessage="Sending voice memory · "+offset*100/wav.length()+"%";store.syncProgress=.25f+.7f*(float)offset/wav.length();}}
    reply=request(ble,base,"commit");if(!reply.optBoolean("done"))throw new IOException("Recording commit not confirmed");}
   synchronized(store){job(store,token).put("audioDelivered",true);activeUpload="";store.save();}
   String target=String.format(Locale.ROOT,"note_%03d.wav",Integer.parseInt(id.substring(1)));File copy=store.safeFile(target),part=new File(copy.getPath()+".part");Files.copy(wav.toPath(),part.toPath(),StandardCopyOption.REPLACE_EXISTING);Files.move(part.toPath(),copy.toPath(),StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);synchronized(store){store.state.getJSONObject("files").put(target,hash);job(store,token).put("status","done").put("file",target).put("retryAt",0).put("uploadAttempts",0).remove("uploadError");store.save();}if(!wav.getCanonicalPath().equals(copy.getCanonicalPath()))wav.delete();changed=true;
  }return changed;}catch(Exception error){if(!(error instanceof Store.SyncDeferredException)&&!currentToken.isEmpty())synchronized(store){JSONObject failed=job(store,currentToken);if(!failed.optString("status").equals("done")){int attempt=failed.optInt("uploadAttempts")+1;failed.put("status","ready").put("uploadAttempts",attempt).put("uploadError","Audio kept on phone; transfer will retry").put("retryAt",System.currentTimeMillis()+Math.min(300000L,15000L*(1L<<Math.min(attempt,5))));store.save();}}android.util.Log.w("PikaVoiceUpload","Transfer stopped: "+error.getClass().getSimpleName()+": "+error.getMessage());throw error;}finally{activeUpload="";android.util.Log.i("PikaVoiceUpload","bytes="+sent+" elapsedMs="+(System.currentTimeMillis()-started)+" complete="+changed);if(ble.online&&ble.session==connection&&!ble.deviceBusy)try{ble.rpc("/api/phone/lease","GET",null,new JSONObject().put("active",false));}catch(Exception ignored){}}
 }
 static JSONObject chunkForWire(JSONObject base,long offset,byte[] buffer,int count)throws Exception{
  for(int n=count;n>0;n/=2){JSONObject chunk=new JSONObject(base.toString()).put("action","chunk").put("offset",offset).put("data",android.util.Base64.encodeToString(Arrays.copyOf(buffer,n),android.util.Base64.NO_WRAP));JSONObject envelope=new JSONObject().put("path","/api/phone/voice-audio").put("method","POST").put("body",chunk.toString()).put("args",new JSONObject()).put("bulk",true);if(envelope.toString().getBytes(StandardCharsets.UTF_8).length<=60000)return chunk;}
  throw new IOException("Recording chunk cannot fit transfer envelope");
 }
 static JSONObject request(BleTransport ble,JSONObject data,String action)throws Exception{JSONObject request=new JSONObject(data.toString()).put("action",action);for(int tries=0;tries<1500;tries++){if(!ble.online||ble.deviceBusy)throw new Store.SyncDeferredException();BleTransport.Reply reply=ble.rpc("/api/phone/voice-audio","POST",request.toString(),null);if(reply.status==202){Thread.sleep(100);continue;}if(reply.status>=400)throw new IOException(reply.json().optString("error","Recording transfer failed"));return reply.json();}throw new IOException("Recording verification timed out; WAV kept on phone");}
 static String hash(File file)throws Exception{MessageDigest sha=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(file)){byte[] buf=new byte[16384];int n;while((n=in.read(buf))>=0)if(n>0)sha.update(buf,0,n);}return BleTransport.hex(sha.digest());}
}
